bool phosphorGeometry(const QString &name, QPainterPath &path) {
    const auto key = name.toLatin1();
    const auto end = std::end(icons);
    const auto found = std::lower_bound(std::begin(icons), end, key, [](const Icon &icon, const QByteArray &wanted) {
        return std::strcmp(icon.name, wanted.constData()) < 0;
    });
    if (found == end || key != found->name) return false;
    found->build(path);
    return true;
}
